export const DIGITS = 1;
export const UPPER = 2;
export const LOWER = 4;
export const PUNCTUATION = 8;

const KNOWN_FLAGS = DIGITS | UPPER | LOWER | PUNCTUATION;

export function alphabet(flags: number): string {
  if (!Number.isInteger(flags) || flags <= 0 || (flags & ~KNOWN_FLAGS) !== 0) {
    throw new RangeError('Invalid character flags');
  }
  let result = '';
  if ((flags & DIGITS) !== 0) result += '0123456789';
  if ((flags & UPPER) !== 0) result += 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  if ((flags & LOWER) !== 0) result += 'abcdefghijklmnopqrstuvwxyz';
  if ((flags & PUNCTUATION) !== 0) result += '-_.';
  return result;
}

export function characterAt(index: number, flags: number): string {
  const characters = alphabet(flags);
  if (!Number.isInteger(index) || index < 0 || index >= characters.length) {
    throw new RangeError('Character index is out of range');
  }
  return characters[index];
}

export function repeatText(value: string, count: number): string {
  if (!Number.isInteger(count) || count < 0) {
    throw new RangeError('Count must be a non-negative integer');
  }
  return value.repeat(count);
}

export function toNarrowAscii(value: string): string {
  let result = '';
  for (const character of value) {
    const code = character.codePointAt(0)!;
    if (code >= 0xff01 && code <= 0xff5e) result += String.fromCodePoint(code - 0xfee0);
    else result += character;
  }
  return result;
}

