import {
  DIGITS,
  UPPER,
  LOWER,
  PUNCTUATION,
  alphabet,
  characterAt,
  repeatText,
  toNarrowAscii,
} from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function rangeError(fn: () => unknown): void {
  try {
    fn();
  } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error('expected RangeError');
  }
  throw new Error('expected RangeError');
}

equal(DIGITS, 1, 'DIGITS');
equal(UPPER, 2, 'UPPER');
equal(LOWER, 4, 'LOWER');
equal(PUNCTUATION, 8, 'PUNCTUATION');
equal(alphabet(DIGITS), '0123456789', 'digit alphabet');
equal(alphabet(UPPER | LOWER), 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', 'letter order');
equal(alphabet(DIGITS | UPPER | LOWER | PUNCTUATION), '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_.', 'all sets');
equal(alphabet(PUNCTUATION), '-_.', 'punctuation set');
rangeError(() => alphabet(0));
rangeError(() => alphabet(16));
rangeError(() => alphabet(DIGITS | 32));

equal(characterAt(0, DIGITS | UPPER), '0', 'first character');
equal(characterAt(9, DIGITS | UPPER), '9', 'digit boundary');
equal(characterAt(10, DIGITS | UPPER), 'A', 'set boundary');
equal(characterAt(35, DIGITS | UPPER), 'Z', 'last character');
rangeError(() => characterAt(-1, DIGITS));
rangeError(() => characterAt(1.5, DIGITS));
rangeError(() => characterAt(Number.NaN, DIGITS));
rangeError(() => characterAt(10, DIGITS));
rangeError(() => characterAt(0, 0));

equal(repeatText('ab', 3), 'ababab', 'repeat text');
equal(repeatText('unchanged', 0), '', 'zero repetitions');
equal(repeatText('', 5), '', 'empty text');
rangeError(() => repeatText('x', -1));
rangeError(() => repeatText('x', 2.25));
rangeError(() => repeatText('x', Number.POSITIVE_INFINITY));

const original = 'ＡＢＣ１２３！～　plain é 😀';
equal(toNarrowAscii(original), 'ABC123!~ plain é 😀', 'full-width conversion');
equal(original, 'ＡＢＣ１２３！～　plain é 😀', 'source string remains unchanged');
equal(toNarrowAscii(''), '', 'empty conversion');
equal(toNarrowAscii('\uFF00\uFF5F'), '\uFF00\uFF5F', 'characters outside conversion range');
assert(toNarrowAscii('abc') === 'abc', 'ordinary ASCII remains unchanged');

